private static readonly Func<AppDb, int, Task<Order?>> _getById =
    EF.CompileAsyncQuery((AppDb db, int id) =>
        db.Orders.FirstOrDefault(o => o.Id == id));

public Task<Order?> GetAsync(int id) => _getById(_db, id);
